# Nice one! You only need to test divisors up to the square root, which keeps it quick for you.
import math

def is_prime(n):
    # 0, 1 and negatives aren't prime, so we set those aside first for you.
    if n < 2:
        return False
    # Any factor bigger than the square root pairs with a smaller one, so stop there.
    for d in range(2, math.isqrt(n) + 1):
        if n % d == 0:
            return False
    return True

print(is_prime(97))  # True

