import math

def is_prime(n):
    # 0, 1 and negative numbers are not prime and are rejected immediately.
    if n < 2:
        return False
    # Any factor above the square root pairs with one below it; stop there.
    for d in range(2, math.isqrt(n) + 1):
        if n % d == 0:
            return False
    return True

