# Great question; there's a really tidy way in modern Python that you'll love.
defaults = {"theme": "light", "size": 12}
user = {"size": 14}

# The right-hand side wins on shared keys, so your user's choices take priority.
merged = defaults | user
# On older Pythons, unpacking both does the same job for you.
merged_old = {**defaults, **user}
print(merged)  # {'theme': 'light', 'size': 14}

